import React, { useState } from 'react';
import { ArrowLeft, ChevronRight, FileText, LockKeyhole, ShieldCheck } from 'lucide-react';
import { Link } from 'react-router-dom';
import {
  LEGAL_CONFIG, TERMS_AND_CONDITIONS_SECTIONS, PRIVACY_POLICY_SECTIONS,
} from '../../config/legal';
import './LegalExperience.css';

interface LegalDocumentPageProps {
  kind: 'terms' | 'privacy';
}

/**
 * Editorial full-page legal reader, with the versioned policy copy preserved.
 * It never substitutes autogenerated terms for the project legal configuration.
 */
export const LegalDocumentPage: React.FC<LegalDocumentPageProps> = ({ kind }) => {
  const [activeId, setActiveId] = useState('');
  const isTerms = kind === 'terms';
  const sections = isTerms ? TERMS_AND_CONDITIONS_SECTIONS : PRIVACY_POLICY_SECTIONS;
  const title = isTerms ? 'Terms of Service' : 'Privacy Policy';
  const version = isTerms ? LEGAL_CONFIG.TERMS_VERSION : LEGAL_CONFIG.PRIVACY_POLICY_VERSION;
  const effective = isTerms ? LEGAL_CONFIG.TERMS_EFFECTIVE_DATE : LEGAL_CONFIG.PRIVACY_EFFECTIVE_DATE;

  const selectSection = (id: string) => {
    setActiveId(id);
    document.getElementById('legal-doc-' + kind + '-' + id)
      ?.scrollIntoView({
        behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth',
        block: 'start',
      });
  };

  return (
    <div className="legal-studio__page">
      <header className="legal-studio__page-topbar">
        <div className="legal-studio__page-topbar-inner">
          <Link to="/signup" className="legal-studio__page-brand">
            <span className="legal-studio__page-brand-mark"><ShieldCheck size={19}/></span>
            <span>Verif<span>AI</span></span>
          </Link>
          <nav className="legal-studio__page-links" aria-label="Legal documents">
            <Link to="/signup"><ArrowLeft size={14}/> Signup</Link>
            <Link to="/terms" className={isTerms ? 'is-active' : ''}><FileText size={14}/> Terms</Link>
            <Link to="/privacy" className={!isTerms ? 'is-active' : ''}><LockKeyhole size={14}/> Privacy</Link>
          </nav>
        </div>
      </header>

      <section className="legal-studio__page-hero">
        <div className="legal-studio__page-hero-inner">
          <div className="legal-studio__page-hero-text">
            <span className="legal-studio__page-overline">VERIFAI / THE POLICY LIBRARY</span>
            <h1>{title}<span style={{ color: '#78B994' }}>.</span></h1>
            <p>{isTerms
              ? 'A readable guide to the responsibilities, conditions and rules that govern using the VerifAI platform.'
              : 'Understand the information we handle, how it is used and the controls that apply to your VerifAI account.'}
            </p>
            <div className="legal-studio__page-hero-metadata">
              <span>Effective {effective}</span>
              <span>Version {version}</span>
              <span>{sections.length} sections</span>
            </div>
          </div>
          <div className="legal-studio__page-hero-art">
            <img src="/auth/verifai-trust-art.webp"
              alt="Verification illustration with a shield, evidence documents, and magnifying glass"/>
          </div>
        </div>
      </section>

      <div className="legal-studio__page-body">
        <aside className="legal-studio__page-nav">
          <span>ON THIS PAGE / {String(sections.length).padStart(2, '0')}</span>
          <nav aria-label={title + ' table of contents'}>
            {sections.map((section, index) => (
              <button key={section.id} type="button"
                className={activeId === section.id ? 'is-active' : ''}
                onClick={() => selectSection(section.id)}>
                <span>{String(index + 1).padStart(2, '0')}</span>
                {section.title.replace(/^\d+\.\s*/, '')}
                <ChevronRight size={13} aria-hidden="true"/>
              </button>
            ))}
          </nav>
        </aside>

        <main className="legal-studio__page-article">
          <div className="legal-studio__draft-note" role="note">
            <span className="legal-studio__note-dot"/>
            <p><strong>Operational draft — not yet approved for commercial launch.</strong>
              {' '}Legal-contact information, governing jurisdiction, and other configuration placeholders must be reviewed and finalized by qualified counsel.
            </p>
          </div>

          {sections.map((section, index) => (
            <section className="legal-studio__page-section" key={section.id}
              id={'legal-doc-' + kind + '-' + section.id}>
              <div className="legal-studio__page-section-number">{String(index + 1).padStart(2, '0')}</div>
              <div>
                <h2>{section.title.replace(/^\d+\.\s*/, '')}</h2>
                {section.content.map((paragraph, index2) => <p key={index2}>{paragraph}</p>)}
              </div>
            </section>
          ))}
          <div className="legal-studio__document-end">
            <ShieldCheck size={18}/>
            <span>Questions about this document? {LEGAL_CONFIG.LEGAL_CONTACT_EMAIL}</span>
          </div>
        </main>
      </div>

      <footer className="legal-studio__page-foot">
        <span>© {new Date().getFullYear()} VerifAI · Evidence-led verification</span>
        <Link to="/signup">Return to signup</Link>
      </footer>
    </div>
  );
};

export default LegalDocumentPage;
